/* Puff · 来自星星的艺术家 · 桌面完整主题（修复 p 字版）
   像素星空，星星闪烁，流星划落 */

/* ========== A. 变量 ========== */
.device {
  --star-void:      #0A0E27;
  --star-navy:      #0F1B3D;
  --star-navy-2:    #141f47;
  --star-cyan:      #5EDCF4;
  --star-pink:      #F0A6CA;
  --star-yellow:    #F4D03F;
  --star-lavender:  #E2D5F2;
  --star-white:     #FFFFFF;
  --star-dim:       #6b7aa8;

  --dress-desk-glass:        rgba(15, 27, 61, 0.78);
  --dress-desk-glass-strong: rgba(20, 31, 71, 0.92);
  --dress-desk-glass-border: rgba(94, 220, 244, 0.22);
  --dress-app-ico-radius: 4px;
  --dress-app-label-size: 10px;
  --dress-app-label-tracking: 0.08em;
  --dress-wg-radius: 4px;

  --glass: var(--dress-desk-glass);
  --glass-strong: var(--dress-desk-glass-strong);
  --glass-border: var(--dress-desk-glass-border);

  --star-font-pixel: "PingFang SC", "Noto Sans SC", "HarmonyOS Sans SC",
                     system-ui, sans-serif;
  --star-font-ui: "PingFang SC", "Noto Sans SC", "HarmonyOS Sans SC",
                  system-ui, sans-serif;

  --stu-grid-gap-x: 22px;
  --stu-grid-gap-y: 26px;
  --stu-ico-scale: 0.88;

  --stu-wg-pad: 12px;
  --stu-wg-gap: 14px;
  --stu-wg-radius: 4px;
  --stu-wg-head-h: 132px;
  --stu-avatar-size: 42px;
  --stu-wg-row-gap: 14px;

  --stu-dock-pad: 10px;
  --stu-dock-gap: 14px;
  --stu-dock-ico: 46px;
}

html[data-theme="dark"] .device {
  --dress-desk-glass:        rgba(15, 27, 61, 0.78);
  --dress-desk-glass-strong: rgba(20, 31, 71, 0.92);
  --dress-desk-glass-border: rgba(94, 220, 244, 0.22);
}

/* ========== A2. 全局兜底 ========== */
html, body {
  width: 100%;
  margin: 0;
  padding: 0;
  overflow-x: hidden;
}

/* ========== B. 设备壳 / 画布 / 状态栏 ========== */
.desk {
  width: 100%;
  min-width: 100%;
  background-color: var(--star-void);
  background-image:
    linear-gradient(rgba(94, 220, 244, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(94, 220, 244, 0.04) 1px, transparent 1px),
    linear-gradient(180deg,
      var(--star-navy-2) 0%,
      var(--star-navy) 45%,
      var(--star-void) 100%);
  background-size: 8px 8px, 8px 8px, 100% 100%;
  color: var(--star-lavender);
  font-family: var(--star-font-ui);
}

/* —— 关键修复：强制清空 .desk 的伪元素，防止 Puff 原有字符露出 —— */
.desk::before,
.desk::after {
  content: none !important;
  display: none !important;
  background: none !important;
  box-shadow: none !important;
  animation: none !important;
}

.status {
  color: var(--star-cyan);
  font-family: var(--star-font-pixel);
  font-size: 0.78em;
  letter-spacing: 0.16em;
  text-shadow:
    2px 2px 0 rgba(10, 14, 39, 0.9),
    0 0 8px rgba(94, 220, 244, 0.4);
}

/* ========== C. 应用图标（像素方块） ========== */
.tile.app {
  padding: 4px;
  min-height: 0;
  overflow: hidden;
}

.app-box {
  padding: 2px 0;
}

.app-box .ico {
  border-radius: var(--dress-app-ico-radius);
  border: 2px solid rgba(94, 220, 244, 0.4);
  transform: scale(var(--stu-ico-scale));
  transform-origin: center bottom;
  box-shadow:
    4px 4px 0 0 rgba(10, 14, 39, 0.9),
    4px 4px 0 2px rgba(94, 220, 244, 0.12);
  transition: transform 0.1s steps(2, end), box-shadow 0.1s steps(2, end);
}
.app-box:active .ico {
  transform: scale(var(--stu-ico-scale)) translate(3px, 3px);
  box-shadow:
    1px 1px 0 0 rgba(10, 14, 39, 0.9);
}

.app-box span {
  font-size: var(--dress-app-label-size);
  letter-spacing: var(--dress-app-label-tracking);
  font-family: var(--star-font-pixel);
  color: var(--star-lavender);
  margin-top: 4px;
  text-shadow:
    1px 1px 0 rgba(10, 14, 39, 1),
    2px 2px 0 rgba(10, 14, 39, 0.6);
}

.tile.app[data-d="1"] .ico {
  box-shadow:
    6px 6px 0 0 rgba(10, 14, 39, 0.9),
    6px 6px 0 2px rgba(94, 220, 244, 0.15);
}

/* ========== D. 小组件壳 ========== */
.wg-profile,
.wg-hero,
.wg-note,
.wg-quote,
.wg-cd,
.wg-custom {
  border-radius: var(--stu-wg-radius);
  background-color: var(--star-navy-2);
  border: 2px solid rgba(94, 220, 244, 0.22);
  color: var(--star-lavender);
  font-family: var(--star-font-ui);
  box-shadow:
    4px 4px 0 0 rgba(10, 14, 39, 0.9),
    inset 0 0 0 1px rgba(94, 220, 244, 0.05);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  min-height: 0;
  padding: var(--stu-wg-pad);
}

.wg-profile,
.wg-hero {
  height: var(--stu-wg-head-h);
  max-height: var(--stu-wg-head-h);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 6px;
  overflow: visible;
}

.wg-profile img,
.wg-hero img,
.wg-profile .avatar,
.wg-hero .avatar,
.wg-profile [class*="avatar"],
.wg-hero [class*="avatar"],
.wg-profile [class*="face"],
.wg-hero [class*="face"] {
  width: var(--stu-avatar-size);
  height: var(--stu-avatar-size);
  min-width: var(--stu-avatar-size);
  min-height: var(--stu-avatar-size);
  max-width: var(--stu-avatar-size);
  max-height: var(--stu-avatar-size);
  border-radius: 2px;
  object-fit: cover;
  display: block;
  flex-shrink: 0;
  align-self: center;
  overflow: hidden;
  border: 2px solid var(--star-cyan);
  box-shadow: 3px 3px 0 0 rgba(10, 14, 39, 0.9);
  image-rendering: pixelated;
}

.wg-profile > *,
.wg-hero > *,
.wg-note > *,
.wg-quote > *,
.wg-cd > *,
.wg-custom > * {
  max-width: 100%;
}

.wg-profile {
  border-color: rgba(94, 220, 244, 0.32);
}

.wg-hero {
  background-image:
    linear-gradient(rgba(94, 220, 244, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(94, 220, 244, 0.06) 1px, transparent 1px);
  background-size: 12px 12px;
}

.wg-note {
  background-color: rgba(240, 166, 202, 0.14);
  border-color: rgba(240, 166, 202, 0.35);
  color: var(--star-pink);
  padding: 9px 10px 12px;
  font-size: 0.88em;
  line-height: 1.42;
  overflow: hidden;
  box-shadow:
    4px 4px 0 0 rgba(10, 14, 39, 0.9),
    inset 0 0 0 1px rgba(240, 166, 202, 0.06);
}
.wg-note *,
.wg-note p,
.wg-note span,
.wg-note div {
  white-space: normal !important;
  word-break: break-word;
  overflow-wrap: anywhere;
  text-overflow: clip;
  overflow: visible;
  max-width: 100%;
  line-height: 1.42;
}
.wg-note::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 0 16px 16px;
  border-color: transparent transparent rgba(240, 166, 202, 0.18) transparent;
  pointer-events: none;
}

.wg-quote {
  background-color: var(--star-navy-2);
}
.wg-quote::before {
  content: "";
  position: absolute;
  right: 16px;
  top: 14px;
  width: 12px;
  height: 6px;
  border-left: 3px solid var(--star-cyan);
  border-bottom: 3px solid var(--star-cyan);
  transform: rotate(-45deg);
  opacity: 0.9;
  pointer-events: none;
}

.wg-cd {
  background-color: rgba(244, 208, 63, 0.1);
  border-color: rgba(244, 208, 63, 0.35);
  color: var(--star-yellow);
  padding: 10px var(--stu-wg-pad);
  margin-bottom: var(--stu-wg-row-gap);
  box-shadow:
    4px 4px 0 0 rgba(10, 14, 39, 0.9),
    inset 0 0 0 1px rgba(244, 208, 63, 0.08);
}
.wg-cd::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(120% 70% at 20% 0%,
    rgba(244, 208, 63, 0.08) 0%, transparent 60%);
}

.wg-custom::before {
  content: "";
  position: absolute;
  left: -8%;
  top: 44%;
  width: 116%;
  height: 8px;
  background: rgba(94, 220, 244, 0.1);
  pointer-events: none;
}

/* ========== E. 底栏 / Dock（位置一律不动） ========== */
.nav-dock {}

.foot {
  background-color: var(--star-navy-2);
  border: 2px solid rgba(94, 220, 244, 0.22);
  border-radius: 8px;
  padding: var(--stu-dock-pad) calc(var(--stu-dock-pad) + 4px);
  gap: var(--stu-dock-gap);
  box-shadow:
    4px 4px 0 0 rgba(10, 14, 39, 0.9),
    inset 0 0 0 1px rgba(94, 220, 244, 0.05);
}

.foot.dock-mist {
  background-color: rgba(15, 27, 61, 0.82);
  box-shadow: 0 -3px 0 0 rgba(10, 14, 39, 0.6);
}

.foot.dock-slate {
  background-color: var(--star-void);
  border-color: rgba(94, 220, 244, 0.15);
  box-shadow: 0 -4px 0 0 rgba(10, 14, 39, 0.8);
}

.foot.dock-drift {
  background: linear-gradient(180deg,
    var(--star-navy-2) 0%,
    transparent 100%);
  border: none;
  box-shadow: none;
}

.dock-app-ico {
  width: var(--stu-dock-ico);
  height: var(--stu-dock-ico);
  border-radius: 4px;
  border: 2px solid rgba(94, 220, 244, 0.3);
  box-shadow: 3px 3px 0 0 rgba(10, 14, 39, 0.9);
  transition: transform 0.1s steps(2, end), box-shadow 0.1s steps(2, end);
}
.dock-app-ico:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 0 rgba(10, 14, 39, 0.9);
}

.dock-app-empty {
  width: var(--stu-dock-ico);
  height: var(--stu-dock-ico);
  border: 2px dashed rgba(94, 220, 244, 0.25);
  background: transparent;
  border-radius: 4px;
}

/* ========== F. 抽屉 / 选择器 ========== */
.picker {
  background-color: var(--star-navy-2);
  border: 2px solid rgba(94, 220, 244, 0.24);
  border-radius: 6px;
  box-shadow:
    6px 6px 0 0 rgba(10, 14, 39, 0.9),
    inset 0 0 0 1px rgba(94, 220, 244, 0.05);
  color: var(--star-lavender);
  font-family: var(--star-font-ui);
  padding: 14px 16px;
}

/* ========== G. 像素星空 + 闪烁 + 三条流星 ========== */

/* —— G1. 星星层：23 颗星铺满全屏，闪烁 —— */
.device::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  opacity: 1;
  background-image:
    radial-gradient(2px 2px at 8% 12%, rgba(94, 220, 244, 0.95) 50%, transparent 51%),
    radial-gradient(3px 3px at 22% 6%, rgba(226, 213, 242, 0.9) 50%, transparent 51%),
    radial-gradient(2px 2px at 35% 18%, rgba(244, 208, 63, 0.9) 50%, transparent 51%),
    radial-gradient(2px 2px at 48% 8%, rgba(94, 220, 244, 0.85) 50%, transparent 51%),
    radial-gradient(3px 3px at 62% 20%, rgba(240, 166, 202, 0.9) 50%, transparent 51%),
    radial-gradient(2px 2px at 76% 10%, rgba(226, 213, 242, 0.9) 50%, transparent 51%),
    radial-gradient(2px 2px at 90% 22%, rgba(94, 220, 244, 0.85) 50%, transparent 51%),
    radial-gradient(3px 3px at 14% 32%, rgba(244, 208, 63, 0.85) 50%, transparent 51%),
    radial-gradient(2px 2px at 30% 40%, rgba(94, 220, 244, 0.8) 50%, transparent 51%),
    radial-gradient(2px 2px at 52% 34%, rgba(226, 213, 242, 0.9) 50%, transparent 51%),
    radial-gradient(3px 3px at 68% 42%, rgba(240, 166, 202, 0.85) 50%, transparent 51%),
    radial-gradient(2px 2px at 84% 36%, rgba(94, 220, 244, 0.8) 50%, transparent 51%),
    radial-gradient(2px 2px at 6% 54%, rgba(226, 213, 242, 0.85) 50%, transparent 51%),
    radial-gradient(3px 3px at 28% 62%, rgba(244, 208, 63, 0.85) 50%, transparent 51%),
    radial-gradient(2px 2px at 44% 52%, rgba(94, 220, 244, 0.8) 50%, transparent 51%),
    radial-gradient(2px 2px at 60% 66%, rgba(226, 213, 242, 0.85) 50%, transparent 51%),
    radial-gradient(3px 3px at 78% 56%, rgba(240, 166, 202, 0.85) 50%, transparent 51%),
    radial-gradient(2px 2px at 92% 62%, rgba(94, 220, 244, 0.8) 50%, transparent 51%),
    radial-gradient(2px 2px at 18% 78%, rgba(244, 208, 63, 0.8) 50%, transparent 51%),
    radial-gradient(3px 3px at 40% 86%, rgba(94, 220, 244, 0.85) 50%, transparent 51%),
    radial-gradient(2px 2px at 56% 80%, rgba(226, 213, 242, 0.8) 50%, transparent 51%),
    radial-gradient(2px 2px at 72% 88%, rgba(240, 166, 202, 0.85) 50%, transparent 51%),
    radial-gradient(3px 3px at 88% 78%, rgba(244, 208, 63, 0.8) 50%, transparent 51%);
  background-size: 100% 100%;
  background-repeat: no-repeat;
  animation: star-twinkle 4.5s ease-in-out infinite;
}

/* —— G2. 流星一：青白色，从左上到右下 —— */
.device::after {
  content: "";
  position: fixed;
  top: 8%;
  left: 8%;
  width: 3px;
  height: 3px;
  background: var(--star-white);
  border-radius: 0;
  pointer-events: none;
  z-index: 3;
  box-shadow:
    0 0 6px 1px rgba(255, 255, 255, 0.9),
    0 0 14px 3px rgba(94, 220, 244, 0.5),
    -4px -4px 0 0 rgba(255, 255, 255, 0.7),
    -8px -8px 0 0 rgba(94, 220, 244, 0.5),
    -12px -12px 0 0 rgba(94, 220, 244, 0.35),
    -16px -16px 0 0 rgba(94, 220, 244, 0.2),
    -20px -20px 0 0 rgba(94, 220, 244, 0.1);
  animation:
    meteor-move-1 9s linear infinite,
    meteor-fade-1 9s linear infinite;
  will-change: transform, opacity;
}

/* —— G3. 流星二：粉紫色，从右上到左下（改用 .status::before） —— */
.status::before {
  content: "";
  position: fixed;
  top: 12%;
  right: 10%;
  left: auto;
  width: 3px;
  height: 3px;
  background: var(--star-pink);
  border-radius: 0;
  pointer-events: none;
  z-index: 3;
  box-shadow:
    0 0 6px 1px rgba(240, 166, 202, 0.9),
    0 0 14px 3px rgba(240, 166, 202, 0.45),
    4px -4px 0 0 rgba(255, 255, 255, 0.6),
    8px -8px 0 0 rgba(240, 166, 202, 0.5),
    12px -12px 0 0 rgba(240, 166, 202, 0.35),
    16px -16px 0 0 rgba(240, 166, 202, 0.2),
    20px -20px 0 0 rgba(240, 166, 202, 0.1);
  animation:
    meteor-move-2 13s linear 2s infinite,
    meteor-fade-2 13s linear 2s infinite;
  will-change: transform, opacity;
}

/* —— G4. 流星三：金黄色，短促快闪（改用 .status::after） —— */
.status::after {
  content: "";
  position: fixed;
  top: 30%;
  left: 20%;
  width: 2px;
  height: 2px;
  background: var(--star-yellow);
  border-radius: 0;
  pointer-events: none;
  z-index: 3;
  box-shadow:
    0 0 5px 1px rgba(244, 208, 63, 0.9),
    0 0 10px 2px rgba(244, 208, 63, 0.4),
    -3px -3px 0 0 rgba(244, 208, 63, 0.6),
    -6px -6px 0 0 rgba(244, 208, 63, 0.4),
    -9px -9px 0 0 rgba(244, 208, 63, 0.25);
  animation:
    meteor-move-3 6s linear 5s infinite,
    meteor-fade-3 6s linear 5s infinite;
  will-change: transform, opacity;
}

/* 星星闪烁：不规则节奏 */
@keyframes star-twinkle {
  0%   { opacity: 1; }
  14%  { opacity: 0.35; }
  28%  { opacity: 0.95; }
  42%  { opacity: 0.5; }
  58%  { opacity: 1; }
  72%  { opacity: 0.3; }
  86%  { opacity: 0.85; }
  100% { opacity: 1; }
}

/* 流星一：左上 → 右下 */
@keyframes meteor-move-1 {
  0%   { transform: translate3d(0, 0, 0); }
  100% { transform: translate3d(95vw, 95vh, 0); }
}
@keyframes meteor-fade-1 {
  0%   { opacity: 0; }
  6%   { opacity: 1; }
  22%  { opacity: 1; }
  32%  { opacity: 0; }
  100% { opacity: 0; }
}

/* 流星二：右上 → 左下 */
@keyframes meteor-move-2 {
  0%   { transform: translate3d(0, 0, 0); }
  100% { transform: translate3d(-90vw, 95vh, 0); }
}
@keyframes meteor-fade-2 {
  0%   { opacity: 0; }
  5%   { opacity: 1; }
  18%  { opacity: 1; }
  28%  { opacity: 0; }
  100% { opacity: 0; }
}

/* 流星三：短促快闪，斜向 */
@keyframes meteor-move-3 {
  0%   { transform: translate3d(0, 0, 0); }
  100% { transform: translate3d(70vw, 70vh, 0); }
}
@keyframes meteor-fade-3 {
  0%   { opacity: 0; }
  10%  { opacity: 1; }
  30%  { opacity: 1; }
  50%  { opacity: 0; }
  100% { opacity: 0; }
}

/* ========== H. 壁纸全屏铺满 ========== */
.desk,
.wallpaper,
.desk-wallpaper,
.desk-bg,
.home-wallpaper,
[class*="wallpaper"],
[class*="wall-paper"] {
  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;
  width: 100% !important;
  min-width: 100% !important;
  max-width: none !important;
  height: 100% !important;
  min-height: 100% !important;
  min-height: 100vh !important;
  min-height: 100dvh !important;
  margin: 0 !important;
  padding: 0 !important;
  background-size: cover !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
}

[class*="wallpaper"] img,
.desk-bg img,
.home-wallpaper img {
  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  min-width: 100% !important;
  min-height: 100% !important;
  object-fit: cover !important;
  object-position: center center !important;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* ========== I. 减少动效偏好 ========== */
@media (prefers-reduced-motion: reduce) {
  .device::before,
  .device::after,
  .status::before,
  .status::after {
    animation: none !important;
  }
}
